// SecureMessage/src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

import Intro from './components/Intro';
import Register from './components/Register';
import Login from './components/Login';
import FaceRecognition from './components/FaceRecognition';
import Dashboard from './components/Dashboard';
import ViewSendMessages from './components/ViewSendMessages';

function App() {
  return (
    <Router>
      <Routes>
        {/* Intro screen */}
        <Route path="/" element={<Intro />} />

        {/* User Registration */}
        <Route path="/register" element={<Register />} />

        {/* User Login */}
        <Route path="/login" element={<Login />} />

        {/* Face recognition after login */}
        <Route path="/face-recognition" element={<FaceRecognition />} />

        {/* Dashboard to view users */}
        <Route path="/dashboard" element={<Dashboard />} />

        {/* Chat screen for viewing and sending messages */}
        <Route
          path="/messages/:userId"
          element={<ViewSendMessages onBack={() => window.history.back()} />}
        />

        {/* Catch-all route for undefined pages */}
        <Route path="*" element={<h2>404 - Page Not Found</h2>} />
      </Routes>
    </Router>
  );
}

export default App;
